script:
# Defaults for new leads: C-stage starts at C0, engagement starts at Active.
if doc.is_new():
    if not doc.status:
        if frappe.db.exists("CRM Lead Status", "C0"):
            doc.status = "C0"
        else:
            open_statuses = frappe.db.get_all("CRM Lead Status", filters={"type": "Open"}, pluck="name")
            if open_statuses:
                doc.status = open_statuses[0]
            else:
                frappe.throw(_("No open lead statuses configured. Run bench migrate or create a CRM Lead Status with type 'Open'."))
    if not doc.lead_status:
        doc.lead_status = "Active"

# Defensive: any record arriving without lead_status defaults to Active.
if not doc.lead_status:
    doc.lead_status = "Active"

ALLOWED_STATUS_TRANSITIONS = {
    "C0": {"C1", "C2", "C6", "C7"},
    "C1": {"C2", "C6", "C7"},
    "C2": {"C4", "C6", "C7"},
    "C4": set(),
    "C6": set(),
    "C7": set(),
}

ALLOWED_LEAD_STATUS_TRANSITIONS = {
    "Active":            {"Cold-Unresponsive", "Archived"},
    "Cold-Unresponsive": {"Reactivated", "Archived", "Active"},
    "Reactivated":       {"Active", "Cold-Unresponsive", "Archived"},
    "Archived":          {"Active"},
    "Won":               {"Active"},
}

if not doc.is_new():
    old_doc = doc.get_doc_before_save()
    old_status = old_doc.status if old_doc else None
    old_lead_status = old_doc.lead_status if old_doc else None
    new_status = doc.status

    # Auto-flip Reactivated -> Active when the C-stage advances (PRD §7).
    # Auto-flip Cold-Unresponsive -> Active when the C-stage moves at all:
    # a stage change can only happen through a successful contact (Calling Team
    # picking a disposition), which proves the lead is no longer unresponsive.
    # Retry-log cancellation cascades from this via the After-Save script's
    # engagement-upgrade branch.
    if old_status and old_status != new_status and doc.lead_status in ("Reactivated", "Cold-Unresponsive"):
        if doc.lead_status == "Cold-Unresponsive":
            doc.flags.auto_cold_flip = True
        doc.lead_status = "Active"

    # Terminal C-stages (C4 Won, C6 Lost) force engagement to Active.
    if new_status in ("C4", "C6") and doc.lead_status != "Active":
        doc.lead_status = "Active"

    new_lead_status = doc.lead_status

    status_changed = bool(old_status) and old_status != new_status
    lead_status_changed = bool(old_lead_status) and old_lead_status != new_lead_status

    if status_changed or lead_status_changed:
        user_roles = {r["role"] for r in frappe.db.get_all("Has Role", filters={"parent": frappe.session.user, "parenttype": "User"}, fields=["role"])}
        is_privileged = "Administrator" in user_roles or "System Manager" in user_roles or "Sales Head" in user_roles or "Sales Coordinator" in user_roles
        is_qr_gate_bypass = "Administrator" in user_roles or "System Manager" in user_roles
        if not is_privileged:
            if "ASM" in user_roles or "RSM" in user_roles:
                user_node = frappe.db.get_value("CRM Sales Hierarchy", {"user": frappe.session.user}, ["lft", "rgt"], as_dict=True)
                if user_node:
                    downstream = {r[0] for r in frappe.db.sql("SELECT `user` FROM `tabCRM Sales Hierarchy` WHERE lft >= %s AND rgt <= %s", (user_node["lft"], user_node["rgt"])) if r[0]}
                    downstream.add(frappe.session.user)
                    if doc.lead_owner not in downstream:
                        frappe.throw(_("You can only change the status of leads owned by users in your team."))
                else:
                    if doc.lead_owner != frappe.session.user:
                        frappe.throw(_("You can only change the status of leads you own"))
            elif "Jr. Sales Executive" in user_roles:
                if status_changed and new_status not in ("C1", "C2", "C6"):
                    frappe.throw(_("Spotters can only move leads to C1, C2, or C6"))
            elif "Calling Team" in user_roles:
                old_state_ok = old_status == "C0" or old_lead_status in ("Cold-Unresponsive", "Reactivated")
                if not old_state_ok:
                    frappe.throw(_("Calling Team can only manage leads at C0 or with engagement Cold-Unresponsive/Reactivated"))
                if status_changed and new_status not in ("C0", "C1", "C2", "C6", "C7"):
                    frappe.throw(_("Calling Team can only move C-stage to C0, C1, C2, C6, or C7"))
                if lead_status_changed and new_lead_status not in ("Active", "Cold-Unresponsive", "Reactivated", "Archived"):
                    frappe.throw(_("Calling Team can only set engagement to Active, Cold-Unresponsive, Reactivated, or Archived"))
            else:
                if doc.lead_owner != frappe.session.user:
                    frappe.throw(_("You can only change the status of leads you own"))

            # Calling Team may step one C-stage backward on Cold-Unresponsive/Reactivated
            # leads (disposition-driven re-engagement, e.g. C2+Cold -> C1). They cannot
            # regress more than one stage (C2->C0 is blocked). All other roles remain
            # bound to the forward-only map.
            CALLING_TEAM_EXTRA = {"C1": {"C0"}, "C2": {"C1"}}
            if status_changed and old_status in ALLOWED_STATUS_TRANSITIONS:
                allowed_targets = ALLOWED_STATUS_TRANSITIONS.get(old_status, set())
                if "Calling Team" in user_roles:
                    allowed_targets = allowed_targets | CALLING_TEAM_EXTRA.get(old_status, set())
                if new_status not in allowed_targets:
                    frappe.throw(_(f"Cannot move C-stage from {old_status} to {new_status}"))

            if lead_status_changed and old_lead_status in ALLOWED_LEAD_STATUS_TRANSITIONS:
                if new_lead_status not in ALLOWED_LEAD_STATUS_TRANSITIONS.get(old_lead_status, set()):
                    frappe.throw(_(f"Cannot move engagement from {old_lead_status} to {new_lead_status}"))

        # QR-Accepted guard (bypassed only by Administrator / System Manager).
        # Sales Head and Sales Coordinator override ownership/role-set checks
        # above but still must respect the Quote-Accepted gate before C2->C4.
        if not is_qr_gate_bypass:
            if status_changed and old_status == "C2" and new_status == "C4":
                latest_quote_status = frappe.db.get_value(
                    "CRM Quote Request",
                    {"lead": doc.name},
                    "status",
                    order_by="creation desc",
                )
                if latest_quote_status != "Accepted":
                    frappe.throw(
                        _("Cannot advance to C4 (Won) until the Lead Owner has accepted the Quote Request. Open the latest Quote Request and set its status to 'Accepted'."),
                        title=_("Quote Approval Required"),
                    )

old_doc = doc.get_doc_before_save()
old_status = old_doc.status if old_doc else None
old_lead_status = old_doc.lead_status if old_doc else None
new_status = doc.status
new_lead_status = doc.lead_status

if old_doc is None and new_status == "C0":
    frappe.get_doc({
        "doctype": "CRM Task",
        "task_type": "call_lead",
        "title": f"Call Lead — {doc.lead_name or doc.name}",
        "status": "Todo",
        "priority": "Medium",
        "reference_doctype": "CRM Lead",
        "reference_docname": doc.name,
        "description": f"New lead {doc.lead_name or doc.name} has arrived at C0. Make the initial call and log the disposition.",
    }).insert(ignore_permissions=True)

# Direct creation at C1 (referral / lead spotting per PRD §4.1) — enroll in Brevo
# here since the status_changed path below won't fire when old_status is None.
if old_doc is None and new_status == "C1" and doc.email:
    frappe.enqueue(
        "crm.integrations.brevo.api.enroll_in_sequence",
        email=doc.email,
        lead_name=doc.name,
    )

status_changed = bool(old_status) and old_status != new_status
lead_status_changed = bool(old_lead_status) and old_lead_status != new_lead_status

# Retry log cancellation: lead exits the retry-active set (C0 + Active/Cold-Unresponsive/Reactivated),
# or is explicitly Archived.
was_retry_active = old_status == "C0" and old_lead_status in ("Active", "Cold-Unresponsive", "Reactivated")
is_retry_active = new_status == "C0" and new_lead_status in ("Active", "Cold-Unresponsive", "Reactivated")
if (status_changed or lead_status_changed) and was_retry_active and not is_retry_active:
    frappe.enqueue(
        "crm.api.call_log.cancel_retry_log",
        lead_name=doc.name,
        permanent=True,
    )
elif lead_status_changed and new_lead_status == "Archived":
    frappe.enqueue(
        "crm.api.call_log.cancel_retry_log",
        lead_name=doc.name,
        permanent=True,
    )
elif lead_status_changed and old_lead_status == "Cold-Unresponsive" and new_lead_status == "Active":
    # Engagement upgrade within retry-active set: contact was made (e.g. agent picked
    # a "Requirement Confirmed" disposition that doesn't change C-stage, or Script 1's
    # Reactivated→Active auto-flip on C-stage advance). Retry is no longer warranted.
    frappe.enqueue(
        "crm.api.call_log.cancel_retry_log",
        lead_name=doc.name,
        permanent=True,
    )

if status_changed:
    if new_status == "C1" and doc.email:
        frappe.enqueue(
            "crm.integrations.brevo.api.enroll_in_sequence",
            email=doc.email,
            lead_name=doc.name,
        )

    if new_status == "C7":
        # Pool guard: if no users carry the B2F Team role, the handle_fabricator_lead
        # task will be orphaned. Log to Error Log + drop a Notification Log entry
        # in each Sales Head's / Sales Coordinator's bell so the routing isn't silently lost.
        b2f_user_count = frappe.db.count(
            "Has Role",
            filters={"role": "B2F Team", "parenttype": "User"},
        )
        if not b2f_user_count:
            frappe.log_error(
                message=f"Lead {doc.name} routed to C7 but no users have the B2F Team role. The handle_fabricator_lead task will be orphaned until a B2F user is configured.",
                title="C7 routing: empty B2F pool",
            )
            recipients = set(
                frappe.db.get_all(
                    "Has Role",
                    filters={"role": ["in", ["Sales Head", "Sales Coordinator"]], "parenttype": "User"},
                    pluck="parent",
                )
            )
            for sm in recipients:
                try:
                    frappe.get_doc({
                        "doctype": "Notification Log",
                        "subject": "C7 routing: empty B2F pool",
                        "email_content": f"Lead {doc.lead_name or doc.name} routed to C7 but no B2F users are configured. The Handle Fabricator Lead task is orphaned until a B2F user is added.",
                        "for_user": sm,
                        "type": "Alert",
                        "document_type": "CRM Lead",
                        "document_name": doc.name,
                    }).insert(ignore_permissions=True)
                except Exception:
                    pass  # bell-notification is best-effort; Error Log is the source of truth

        if not frappe.db.exists("CRM Task", {
            "reference_doctype": "CRM Lead",
            "reference_docname": doc.name,
            "task_type": "handle_fabricator_lead",
            "status": ["in", ["Todo", "In Progress"]],
        }):
            frappe.get_doc({
                "doctype": "CRM Task",
                "task_type": "handle_fabricator_lead",
                "title": f"Handle Fabricator Lead — {doc.lead_name or doc.name}",
                "status": "Todo",
                "priority": "High",
                "reference_doctype": "CRM Lead",
                "reference_docname": doc.name,
                "description": f"Lead {doc.lead_name} has been routed to you for fabricator handling (C7). Review the fabricator routing reason and partner fabricator name. The lead has exited the active sales pipeline; coordinate with the fabricator externally to close the deal.",
            }).insert(ignore_permissions=True)

# Reactivation stamp: engagement leaves Cold-Unresponsive (PRD §7). C-stage preserved.
if lead_status_changed and old_lead_status == "Cold-Unresponsive" and new_lead_status in ("Reactivated", "Active") and not doc.custom_reactivated_at and not doc.flags.get("auto_cold_flip"):
    frappe.db.set_value("CRM Lead", doc.name, "custom_reactivated_at", frappe.utils.now_datetime())

# Audit comments on engagement transitions.
if lead_status_changed and old_lead_status == "Active" and new_lead_status == "Cold-Unresponsive":
    try:
        frappe.get_doc({
            "doctype": "Comment",
            "comment_type": "Comment",
            "reference_doctype": "CRM Lead",
            "reference_name": doc.name,
            "content": f"[AUTOMATION] Lead moved to Cold-Unresponsive (C-stage preserved at {doc.status}).",
        }).insert(ignore_permissions=True)
    except Exception:
        pass

if lead_status_changed and old_lead_status == "Cold-Unresponsive" and new_lead_status == "Reactivated":
    try:
        frappe.get_doc({
            "doctype": "Comment",
            "comment_type": "Comment",
            "reference_doctype": "CRM Lead",
            "reference_name": doc.name,
            "content": f"[AUTOMATION] Lead reactivated from Cold-Unresponsive (C-stage preserved at {doc.status}).",
        }).insert(ignore_permissions=True)
    except Exception:
        pass

old_doc = doc.get_doc_before_save()
old_status = old_doc.status if old_doc else None

if old_status != doc.status and doc.status == "Quote Received":
    updates = {}
    if doc.quote_value:
        updates["custom_tentative_value"] = doc.quote_value
        updates["custom_final_price"] = doc.quote_value
    if doc.quote_margin:
        updates["custom_final_margin"] = doc.quote_margin
    if doc.quote_file:
        updates["custom_final_quote"] = doc.quote_file
    if doc.quote_sq_ft:
        updates["custom_tentative_area_sqft"] = doc.quote_sq_ft
    if updates:
        frappe.db.set_value("CRM Lead", doc.lead, updates)

    open_upload_task = frappe.db.get_value("CRM Task", {
        "reference_doctype": "CRM Lead",
        "reference_docname": doc.lead,
        "task_type": "upload_quote",
        "status": ["in", ["Todo", "In Progress"]],
    }, "name")
    if open_upload_task:
        frappe.db.set_value("CRM Task", open_upload_task, "status", "Done")

    lead_owner = frappe.db.get_value("CRM Lead", doc.lead, "lead_owner")
    if not frappe.db.exists("CRM Task", {
        "reference_doctype": "CRM Lead",
        "reference_docname": doc.lead,
        "task_type": "review_quote",
        "status": ["in", ["Todo", "In Progress"]],
    }):
        review_task = {
            "doctype": "CRM Task",
            "task_type": "review_quote",
            "title": f"Review & Share Quote — {doc.lead_name or doc.lead}",
            "status": "Todo",
            "priority": "High",
            "reference_doctype": "CRM Lead",
            "reference_docname": doc.lead,
            "quote_request": doc.name,
            "description": f"Quote received for {doc.lead_name or doc.lead} (Value: {doc.quote_value}). Review the quotation and share it with the customer.",
        }
        # Orphan-by-design: if the lead has no owner yet (common on C0->C2 before reassignment), insert the task unassigned -- Sales Head / System Manager triage it via the all-tasks view (see admin-ui-setup-guide.md Script 5 commentary).
        if lead_owner:
            review_task["assigned_to"] = lead_owner
        frappe.get_doc(review_task).insert(ignore_permissions=True)

if old_status != doc.status and doc.status == "Revision Requested":
    # Lead Owner has reviewed and asked for revision — close their stale
    # review_quote task. Script 14 spawns a fresh upload_quote task for
    # Estimation in the same save.
    open_review_task = frappe.db.get_value("CRM Task", {
        "reference_doctype": "CRM Lead",
        "reference_docname": doc.lead,
        "task_type": "review_quote",
        "status": ["in", ["Todo", "In Progress"]],
    }, "name")
    if open_review_task:
        frappe.db.set_value("CRM Task", open_review_task, "status", "Done")

if old_status != doc.status and doc.status == "Accepted":
    # Mark Review & Share task Done
    review_task = frappe.db.get_value("CRM Task", {
        "reference_doctype": "CRM Lead",
        "reference_docname": doc.lead,
        "task_type": "review_quote",
        "status": ["in", ["Todo", "In Progress"]],
    }, "name")
    if review_task:
        frappe.db.set_value("CRM Task", review_task, "status", "Done")

    # No auto-advance: Sales manually moves the lead C2 -> C4 once advance
    # payment is received. Accept just closes the review_quote task; the
    # lead's C-stage stays put. Script 1's task-completion guard enforces
    # that the latest QR must be Accepted before C2 -> C4 succeeds.

old_doc = doc.get_doc_before_save()
old_status = old_doc.status if old_doc else None
new_status = doc.status

if old_doc is not None and old_status != new_status and new_status in ("Quote Received", "Revision Requested", "Accepted"):
    if new_status == "Quote Received":
        parts = []
        if doc.quote_value:
            parts.append(f"Value: {doc.quote_value}")
        if doc.quote_margin:
            parts.append(f"Margin: {doc.quote_margin}%")
        meta = ", ".join(parts) if parts else "Quote uploaded."
        file_link = ""
        if doc.quote_file:
            file_link = f" — <a href='{doc.quote_file}' target='_blank' rel='noopener'>View File</a>"
        content = f"[AUTOMATION] Quote uploaded — {meta}{file_link}"
    elif new_status == "Revision Requested":
        now = frappe.utils.now_datetime()
        for row in (doc.revision_images or []):
            if not row.uploaded_by:
                row.uploaded_by = frappe.session.user
            if not row.uploaded_on:
                row.uploaded_on = now
        reason = doc.revision_notes or "(no reason provided)"
        img_count = len(doc.revision_images or [])
        suffix = f" ({img_count} image(s) attached)" if img_count else ""
        content = f"[AUTOMATION] Quote revision requested: {reason}{suffix}"
    else:
        content = "[AUTOMATION] Quote Accepted. Sales can now record the advance payment and move the lead to C4 (Won)."

    try:
        frappe.get_doc({
            "doctype": "Comment",
            "comment_type": "Comment",
            "reference_doctype": "CRM Lead",
            "reference_name": doc.lead,
            "content": content,
        }).insert(ignore_permissions=True)
    except Exception:
        # Comment is audit-only; never block the save.
        pass

    # Mirror the uploaded quote file onto the parent Lead so every round's PDF
    # surfaces in the Lead's Attachments side panel. Uses create_attachment_copy
    # to clone the File row reusing the same file_url (no disk duplication).
    # Idempotent: skipped when a Lead-attached File with this file_url already
    # exists, so a stray re-save with no file change doesn't double-mirror.
    if new_status == "Quote Received" and doc.quote_file and doc.lead:
        qr_file = frappe.db.get_value(
            "File",
            {
                "attached_to_doctype": "CRM Quote Request",
                "attached_to_name": doc.name,
                "file_url": doc.quote_file,
            },
            "name",
        )
        already_mirrored = frappe.db.exists(
            "File",
            {
                "attached_to_doctype": "CRM Lead",
                "attached_to_name": doc.lead,
                "file_url": doc.quote_file,
            },
        )
        if qr_file and not already_mirrored:
            try:
                frappe.get_doc("File", qr_file).create_attachment_copy(
                    attached_to_doctype="CRM Lead",
                    attached_to_name=doc.lead,
                    ignore_permissions=True,
                )
            except Exception:
                # Mirror is best-effort; the file is still visible on the QR.
                frappe.log_error(
                    message=f"Failed to mirror {doc.quote_file} from QR {doc.name} to lead {doc.lead}",
                    title="Quote file mirror to Lead failed",
                )

    if new_status == "Revision Requested":
        # Insert the successor QR first — only mark current QR superseded if it succeeds.
        try:
            new_qr = frappe.new_doc("CRM Quote Request")
            new_qr.update({"lead": doc.lead, "status": "Pending"})
            new_qr.flags.ignore_mandatory = True
            new_qr.insert(ignore_permissions=True)
        except Exception:
            frappe.log_error(
                message=f"Failed to create successor QR for revision on {doc.name}",
                title="Quote Revision QR Creation Failed",
            )
            frappe.throw(_("Could not create a new Quote Request for the revision round. Please try again."))
        doc.is_superseded = 1
        reason = doc.revision_notes or "(no reason provided)"
        try:
            if not frappe.db.exists("CRM Task", {
                "reference_doctype": "CRM Lead",
                "reference_docname": doc.lead,
                "task_type": "upload_quote",
                "status": ["in", ["Todo", "In Progress"]],
            }):
                frappe.get_doc({
                    "doctype": "CRM Task",
                    "task_type": "upload_quote",
                    "title": f"Upload Revised Quote — {doc.lead_name or doc.lead}",
                    "status": "Todo",
                    "priority": "High",
                    "reference_doctype": "CRM Lead",
                    "reference_docname": doc.lead,
                    "quote_request": new_qr.name,
                    "description": f"Revision requested for lead {doc.lead_name or doc.lead}: {reason}. Open Quote Request {new_qr.name} to upload the revised quote.",
                }).insert(ignore_permissions=True)
        except Exception:
            frappe.log_error(
                message=f"Failed to create upload_quote task for revision on {doc.name}",
                title="Quote Revision Task Creation Failed",
            )

old_doc = doc.get_doc_before_save()
old_assignee = old_doc.assigned_to if old_doc else None
new_assignee = doc.assigned_to

if doc.task_type == "upload_quote" and not old_assignee and new_assignee and doc.reference_doctype == "CRM Lead":
    try:
        frappe.get_doc({
            "doctype": "Comment",
            "comment_type": "Comment",
            "reference_doctype": "CRM Lead",
            "reference_name": doc.reference_docname,
            "content": f"[AUTOMATION] Upload Quote task claimed by {new_assignee}.",
        }).insert(ignore_permissions=True)
    except Exception:
        pass

old_doc = doc.get_doc_before_save()
old_disposition = old_doc.disposition if old_doc else None
new_disposition = doc.disposition

if new_disposition and new_disposition != old_disposition:
    disp = frappe.db.get_value(
        "CRM Call Disposition",
        new_disposition,
        ["next_status", "next_lead_status", "default_lost_reason"],
        as_dict=True,
    ) or {}
    next_status = disp.get("next_status")
    next_lead_status = disp.get("next_lead_status")
    default_reason = disp.get("default_lost_reason")

    if next_status or next_lead_status:
        lead_name = None
        if doc.reference_doctype == "CRM Lead" and doc.reference_docname:
            lead_name = doc.reference_docname
        else:
            for row in (doc.links or []):
                if row.link_doctype == "CRM Lead" and row.link_name:
                    lead_name = row.link_name
                    break
        if lead_name:
            current = frappe.db.get_value(
                "CRM Lead", lead_name, ["status", "lead_status"], as_dict=True
            ) or {}
            gate_ok = current.get("status") == "C0" or current.get("lead_status") in ("Cold-Unresponsive", "Reactivated")
            if gate_ok:
                try:
                    lead = frappe.get_doc("CRM Lead", lead_name)
                    changed = False
                    if next_status and next_status != lead.status:
                        lead.status = next_status
                        changed = True
                    if next_lead_status and next_lead_status != lead.lead_status:
                        lead.lead_status = next_lead_status
                        changed = True
                    if default_reason and not lead.lost_reason:
                        lead.lost_reason = default_reason
                    if changed:
                        lead.save(ignore_permissions=True)
                except Exception:
                    # Disposition still recorded; lead validation (e.g. lost_reason mandatory on C6,
                    # or transition not allowed) blocked the move.
                    frappe.log_error(
                        message=f"Lead {lead_name} could not auto-move for disposition {new_disposition!r}: current_status={current.get('status')}, current_lead_status={current.get('lead_status')}, next_status={next_status}, next_lead_status={next_lead_status}. Lead validation rejected the change. Agent must finalise the stage manually.",
                        title="Disposition stage move skipped — lead validation failed",
                    )

    if new_disposition == "Requested Callback":
        lead_name = None
        if doc.reference_doctype == "CRM Lead" and doc.reference_docname:
            lead_name = doc.reference_docname
        else:
            for row in (doc.links or []):
                if row.link_doctype == "CRM Lead" and row.link_name:
                    lead_name = row.link_name
                    break
        if lead_name:
            lead_state = frappe.db.get_value(
                "CRM Lead", lead_name, ["status", "lead_status"], as_dict=True
            ) or {}
            if lead_state.get("status") == "C0" or lead_state.get("lead_status") in ("Cold-Unresponsive", "Reactivated"):
                frappe.enqueue(
                    "crm.api.call_log.cancel_retry_log",
                    queue="short",
                    lead_name=lead_name,
                    permanent=False,
                )

old_doc = doc.get_doc_before_save()
old_status = old_doc.status if old_doc else None

if doc.status == "Call Not Answered" and old_status != "Call Not Answered":
    lead_name = None
    if doc.reference_doctype == "CRM Lead" and doc.reference_docname:
        lead_name = doc.reference_docname
    else:
        for row in (doc.links or []):
            if row.link_doctype == "CRM Lead" and row.link_name:
                lead_name = row.link_name
                break
    if lead_name:
        lead_state = frappe.db.get_value(
            "CRM Lead", lead_name, ["status", "lead_status"], as_dict=True
        ) or {}
        if lead_state.get("status") == "C0" or lead_state.get("lead_status") in ("Cold-Unresponsive", "Reactivated"):
            frappe.enqueue(
                "crm.api.call_log.register_no_answer",
                queue="short",
                lead_name=lead_name,
            )

old_doc = doc.get_doc_before_save()
old_disposition = old_doc.disposition if old_doc else None
new_disposition = doc.disposition

# Only validate when the disposition value is actually changing.
# (No-op saves and inserts without a disposition are skipped.)
if new_disposition and new_disposition != old_disposition:
    user = frappe.session.user
    user_roles = {r["role"] for r in frappe.db.get_all("Has Role", filters={"parent": user, "parenttype": "User"}, fields=["role"])}
    is_privileged = bool(user_roles & {"System Manager", "Administrator"})

    if not is_privileged and user not in (doc.caller, doc.receiver):
        frappe.throw(
            _("You can only set the disposition on calls you handled."),
            exc=frappe.PermissionError,
            title=_("Not Allowed"),
        )

    # Multiple no-answers escalate to Cold via the retry engine (PRD §5.2);
    # the agent has no discretion to relabel a Call Not Answered call.
    if doc.status == "Call Not Answered" and new_disposition != "No Answer / Not Reachable":
        frappe.throw(
            _("A Call Not Answered call can only be tagged 'No Answer / Not Reachable'."),
            title=_("Disposition Not Allowed"),
        )

    lead_name = None
    if doc.reference_doctype == "CRM Lead" and doc.reference_docname:
        lead_name = doc.reference_docname
    else:
        for row in (doc.links or []):
            if row.link_doctype == "CRM Lead" and row.link_name:
                lead_name = row.link_name
                break

    # Eligibility gate: outcome dispositions are no-ops outside the disposition-eligible set
    # (C0 OR lead_status in Cold-Unresponsive/Reactivated). Mirrors the gate in
    # crm/api/call_log.py:register_no_answer and the After-Save stage-move script.
    # 'No Answer / Not Reachable' stays whitelisted: it is an audit tag set by the
    # system on missed calls; the retry engine has its own gate for side-effects.
    if lead_name and new_disposition != "No Answer / Not Reachable":
        state = frappe.db.get_value("CRM Lead", lead_name, ["status", "lead_status"], as_dict=True) or {}
        eligible = state.get("status") == "C0" or state.get("lead_status") in ("Cold-Unresponsive", "Reactivated")
        if not eligible:
            frappe.throw(
                _(f"Dispositions can only be set on C0 leads or leads with engagement Cold-Unresponsive/Reactivated. Lead {lead_name} is currently at {state.get('status')} / {state.get('lead_status')}."),
                title=_("Disposition Not Allowed"),
            )

    # Per-disposition required fields. Schema lives on CRM Call Disposition
    # (requires_callback_datetime / _routing_reason / _lost_reason). Privileged
    # users are still subject to these — they describe data integrity, not policy.
    disp = frappe.db.get_value(
        "CRM Call Disposition",
        new_disposition,
        ["requires_callback_datetime", "requires_routing_reason", "requires_lost_reason"],
        as_dict=True,
    ) or {}

    if disp.get("requires_callback_datetime") and not doc.get("scheduled_callback_at"):
        frappe.throw(
            _(f"Disposition '{new_disposition}' requires a Scheduled Callback At datetime on this call log."),
            title=_("Callback Datetime Required"),
        )

    if lead_name and disp.get("requires_routing_reason"):
        if not frappe.db.get_value("CRM Lead", lead_name, "custom_fabricator_routing_reason"):
            frappe.throw(
                _(f"Disposition '{new_disposition}' requires Fabricator Routing Reason on the linked lead. Set it on the lead before saving the call."),
                title=_("Routing Reason Required"),
            )

    if lead_name and disp.get("requires_lost_reason"):
        lr = frappe.db.get_value("CRM Lead", lead_name, ["lost_reason", "lost_notes"], as_dict=True) or {}
        if not lr.get("lost_reason"):
            frappe.throw(
                _(f"Disposition '{new_disposition}' requires a Lost Reason on the linked lead. Set it on the lead before saving the call."),
                title=_("Lost Reason Required"),
            )
        if lr.get("lost_reason") == "Other" and not lr.get("lost_notes"):
            frappe.throw(
                _("Lost Reason 'Other' additionally requires Lost Notes on the linked lead."),
                title=_("Lost Notes Required"),
            )
